function validate(input) {
  const [{ Teacher = [] }] = input;
  const seen = new Set();
  for (const [teacher, subject, dept] of Teacher) {
    if (teacher === null || subject === null || dept === null) return 'Teacher rows may not contain null.';
    const key = `${subject}|${dept}`;
    if (seen.has(key)) return `Subject ${subject} appears twice in department ${dept}.`;
    seen.add(key);
  }
  return null;
}

