function generate(rand, size) {
  const small = size === 'small';
  const teachers = small ? 4 : 300, subjects = small ? 4 : 100, depts = small ? 4 : 40;
  const target = small ? Math.floor(rand() * 9) : 2000;
  const used = new Set(), Teacher = [];
  let tries = 0;
  while (Teacher.length < target && tries < target * 20) {
    tries++;
    const subject = 1 + Math.floor(rand() * subjects), dept = 1 + Math.floor(rand() * depts);
    const key = `${subject}|${dept}`;
    if (used.has(key)) continue;
    used.add(key);
    Teacher.push([1 + Math.floor(rand() * teachers), subject, dept]);
  }
  return [{ Teacher }];
}
